// sum.test.js
const test = require('node:test');
const assert = require('node:assert');

function sum(a, b) {
  return a + b;
}

test('sum(1, 2)는 3을 반환한다', () => {
  assert.strictEqual(sum(1, 2), 3);
});

test('sum(-1, 1)은 0을 반환한다', () => {
  assert.strictEqual(sum(-1, 1), 0);
});

// 실행: node --test
